package command

import (
	"{{.Module}}/sandbox/api"
)

// NewCommand is the generic base every command's generated NewCommand builds
// on: an empty declaration with IsActionable and CommandHandler closed over
// the sandbox, so every command matches and binds a command line the same way.
// Generated by `{{.GeneratorName}} build` — do not edit by hand.
func NewCommand(sandbox *api.Sandbox) *api.Command {
	self := api.NewCommand()

	self.IsActionable = func(bound *api.Command) bool {
		return IsActionable(sandbox, bound)
	}
	self.CommandHandler = func(bound *api.Command) error {
		return CommandHandler(sandbox, bound)
	}

	return self
}
